Процедура NDFL_RDU_ПривестиСнимокОбработкиНДФЛКУнифицированномуВиду(Снимок)

	ЗначПериод = Неопределено;
	ПериодУжеЕсть = Ложь;
	Если Снимок.Свойство("Период", ЗначПериод) И ЗначПериод <> Неопределено
		И ТипЗнч(ЗначПериод) = Тип("СтандартныйПериод") Тогда

		Если ЗначениеЗаполнено(ЗначПериод.ДатаНачала) Или ЗначениеЗаполнено(ЗначПериод.ДатаОкончания) Тогда
			ПериодУжеЕсть = Истина;
		КонецЕсли;
	КонецЕсли;

	Если ПериодУжеЕсть Тогда
		Возврат;
	КонецЕсли;

	ДатаНачалаСнимка = Неопределено;
	ДатаОкончанияСнимка = Неопределено;
	Если Не Снимок.Свойство("ПериодДатаНачала", ДатаНачалаСнимка)
		Или Не Снимок.Свойство("ПериодДатаОкончания", ДатаОкончанияСнимка) Тогда

		Возврат;
	КонецЕсли;

	Если ЗначениеЗаполнено(ДатаНачалаСнимка) Или ЗначениеЗаполнено(ДатаОкончанияСнимка) Тогда
		Период = Новый СтандартныйПериод(ДатаНачалаСнимка, ДатаОкончанияСнимка);
		Снимок.Вставить("Период", Период);
	Иначе
		Снимок.Вставить("Период", Новый СтандартныйПериод);
	КонецЕсли;

КонецПроцедуры

