Функция NDFL_RDU_СнимокОбъектаОбработки(ОбъектОбработки) Экспорт

	Снимок = Новый Структура;
	Мета = ОбъектОбработки.Метаданные();

	Для Каждого МетаРек Из Мета.Реквизиты Цикл
		ИмяРеквизита = МетаРек.Имя;
		Попытка
			Снимок.Вставить(ИмяРеквизита, ОбъектОбработки[ИмяРеквизита]);
		Исключение
		КонецПопытки;
	КонецЦикла;

	Для Каждого МетаТЧ Из Мета.ТабличныеЧасти Цикл
		ИмяТЧ = МетаТЧ.Имя;
		Попытка
			Снимок.Вставить(ИмяТЧ, ОбъектОбработки[ИмяТЧ].Выгрузить());
		Исключение
		КонецПопытки;
	КонецЦикла;

	NDFL_RDU_ДополнитьСнимокПослеУниверсальнойСборкиНДФЛ(Снимок, ОбъектОбработки);

	Возврат Снимок;

КонецФункции

