Процедура NDFL_RDU_ЗаполнитьОбъектОбработкиИзСнимка(ОбъектОбработки, Снимок) Экспорт

	NDFL_RDU_ПривестиСнимокОбработкиНДФЛКУнифицированномуВиду(Снимок);

	Мета = ОбъектОбработки.Метаданные();

	Для Каждого МетаРек Из Мета.Реквизиты Цикл
		ИмяРеквизита = МетаРек.Имя;
		ЗначениеРеквизита = Неопределено;
		Если Не Снимок.Свойство(ИмяРеквизита, ЗначениеРеквизита) Тогда
			Продолжить;
		КонецЕсли;
		Попытка
			ОбъектОбработки[ИмяРеквизита] = ЗначениеРеквизита;
		Исключение
		КонецПопытки;
	КонецЦикла;

	Для Каждого МетаТЧ Из Мета.ТабличныеЧасти Цикл
		ИмяТЧ = МетаТЧ.Имя;
		ЗначениеТЧ = Неопределено;
		Если Не Снимок.Свойство(ИмяТЧ, ЗначениеТЧ) Тогда
			Продолжить;
		КонецЕсли;
		Если ТипЗнч(ЗначениеТЧ) <> Тип("ТаблицаЗначений") Тогда
			Продолжить;
		КонецЕсли;
		Попытка
			ОбъектОбработки[ИмяТЧ].Загрузить(ЗначениеТЧ.Скопировать());
		Исключение
		КонецПопытки;
	КонецЦикла;

КонецПроцедуры

