Функция NDFL_RDU_КлонироватьСнимок(ИсходныйСнимок)

	Копия = Новый Структура;
	Для Каждого КлючИЗначение Из ИсходныйСнимок Цикл
		ЗначениеПоля = КлючИЗначение.Значение;
		Если ТипЗнч(ЗначениеПоля) = Тип("ТаблицаЗначений") Тогда
			Копия.Вставить(КлючИЗначение.Ключ, ЗначениеПоля.Скопировать());
		Иначе
			Копия.Вставить(КлючИЗначение.Ключ, ЗначениеПоля);
		КонецЕсли;
	КонецЦикла;

	Возврат Копия;

КонецФункции

