Функция NDFL_RDU_ОркестраторВыполнитьОжиданиеПачек(Снимок, АдресРезультата, АдресПрогресса, МассивИдентификаторовЗаданийПачек,
	ПачкиИндексов, ИдентификаторФормы)

	Пока Истина Цикл

		ЗаданиеРодителя = ПолучитьТекущийСеансИнформационнойБазы().ПолучитьФоновоеЗадание();
		Если ЗаданиеРодителя <> Неопределено
			И ЗаданиеРодителя.Состояние = СостояниеФоновогоЗадания.Отменено Тогда

			NDFL_RDU_ОтменитьЗаданияПачек(МассивИдентификаторовЗаданийПачек);
			ТабОтмена = Новый ТабличныйДокумент;
			NDFL_RDU_ЗаписатьРезультатОркестратораВоВременноеХранилище(АдресРезультата, Ложь,
				НСтр("ru = 'Формирование НДФЛ прервано по запросу пользователя.'"), ТабОтмена, Снимок,
				Истина, Новый Массив);
			Возврат Истина;

		КонецЕсли;

		ВсеЗавершены = Истина;
		Для Каждого ИдентификаторЗаданияПачки Из МассивИдентификаторовЗаданийПачек Цикл
			Задание = NDFL_RDU_ФоновоеЗаданиеПачкиПоИдентификатору(ИдентификаторЗаданияПачки);
			Если Задание = Неопределено Тогда
				Продолжить;
			КонецЕсли;
			Если Задание.Состояние = СостояниеФоновогоЗадания.Активно Тогда
				ВсеЗавершены = Ложь;
				Попытка
					Задание.ОжидатьЗавершенияВыполнения(0.2);
				Исключение
					// IMDEV-7330-5 Короткая пауза; по таймауту переходим к следующей итерации цикла.
				КонецПопытки;
			КонецЕсли;
		КонецЦикла;

		NDFL_RDU_ОбновитьПрогрессОркестратораПоЗаданиям(АдресПрогресса, МассивИдентификаторовЗаданийПачек,
			ПачкиИндексов, ИдентификаторФормы);

		Если ВсеЗавершены Тогда
			Прервать;
		КонецЕсли;

	КонецЦикла;

	ТекстыСообщенийПачек = Новый Соответствие;
	Для Каждого ИдентификаторЗаданияПачки Из МассивИдентификаторовЗаданийПачек Цикл
		Задание = NDFL_RDU_ФоновоеЗаданиеПачкиПоИдентификатору(ИдентификаторЗаданияПачки);
		Если Задание = Неопределено Тогда
			Продолжить;
		КонецЕсли;

		Попытка
			Для Каждого Сообщение Из Задание.ПолучитьСообщенияПользователю(Ложь) Цикл
				ТекстСообщения = СокрЛП(Сообщение.Текст);
				Если ПустаяСтрока(ТекстСообщения) Тогда
					Продолжить;
				КонецЕсли;

				Если ТекстыСообщенийПачек.Получить(ТекстСообщения) <> Неопределено Тогда
					Продолжить;
				КонецЕсли;

				ТекстыСообщенийПачек.Вставить(ТекстСообщения, Истина);
				ОбщегоНазначенияКлиентСервер.СообщитьПользователю(ТекстСообщения);
			КонецЦикла;
		Исключение
			ЗаписьЖурналаРегистрации(НСтр("ru = 'IMDEV-7330. Чтение сообщений фонового задания пачки НДФЛ'"),
				УровеньЖурналаРегистрации.Предупреждение, , , ПодробноеПредставлениеОшибки(ИнформацияОбОшибке()));
		КонецПопытки;
	КонецЦикла;

	Возврат Ложь;

КонецФункции

