Функция NDFL_RDU_ТабличныйДокументИзМногострочногоТекста(Текст)

	Результат = Новый ТабличныйДокумент;
	Если ПустаяСтрока(Текст) Тогда
		Возврат Результат;
	КонецЕсли;

	Части = СтрРазделить(Текст, Символы.ПС);
	НомерСтроки = 1;
	Для Каждого Часть Из Части Цикл
		Результат.Область(НомерСтроки, 1, НомерСтроки, 1).Текст = Часть;
		НомерСтроки = НомерСтроки + 1;
	КонецЦикла;

	Возврат Результат;

