Процедура NDFL_RDU_ОбновитьПрогрессОркестратораПоЗаданиям(АдресПрогресса, МассивИдентификаторовЗаданийПачек, ПачкиИндексов,
	ИдентификаторФормы)

	Прогресс = ПолучитьИзВременногоХранилища(АдресПрогресса);
	Если Прогресс = Неопределено Тогда
		Возврат;
	КонецЕсли;

	ЗавершеноПачек = 0;
	ОбработаноСтрок = 0;
	Номер = 0;
	Для Каждого ИдентификаторЗаданияПачки Из МассивИдентификаторовЗаданийПачек Цикл
		Номер = Номер + 1;
		Задание = NDFL_RDU_ФоновоеЗаданиеПачкиПоИдентификатору(ИдентификаторЗаданияПачки);
		ПачкаЗавершена = (Задание = Неопределено)
			Или Задание.Состояние <> СостояниеФоновогоЗадания.Активно;
		Если ПачкаЗавершена Тогда
			ЗавершеноПачек = ЗавершеноПачек + 1;
			Если Номер <= ПачкиИндексов.Количество() Тогда
				ОбработаноСтрок = ОбработаноСтрок + ПачкиИндексов[Номер - 1].Количество();
			КонецЕсли;
		КонецЕсли;
	КонецЦикла;

	Прогресс.ЗавершеноПачек = ЗавершеноПачек;
	Прогресс.ОбработаноСтрок = ОбработаноСтрок;
	Процент = 0;
	Если Прогресс.ВсегоСтрок > 0 Тогда
		Процент = Окр(100 * ОбработаноСтрок / Прогресс.ВсегоСтрок, 0);
	КонецЕсли;

	ВремяСтартаТекст = "";
	Если Не Прогресс.Свойство("ВремяСтартаТекст", ВремяСтартаТекст) Тогда
		ВремяСтартаТекст = "";
	КонецЕсли;

	ВремяСтартаМС = 0;
	Если Не Прогресс.Свойство("ВремяСтартаМС", ВремяСтартаМС) Тогда
		ВремяСтартаМС = 0;
	КонецЕсли;

	ТекстПрошло = NDFL_RDU_СтрокаПрошедшихМинутСекунд(ВремяСтартаМС);
	ТекстПачек = СтрШаблон(
		НСтр("ru = '%2Клиентов к расчету: %1%2Завершено потоков %3 из %4%2Время старта: %5%2Прошло мин:сек %6'"),
		Прогресс.ВсегоСтрок,
		Символы.ПС,
		ЗавершеноПачек,
		Прогресс.ВсегоПачек,
		ВремяСтартаТекст,
		ТекстПрошло);
	Прогресс.ТекстЭтапа = ТекстПачек;
	ПоместитьВоВременноеХранилище(Прогресс, АдресПрогресса);
	ДлительныеОперации.СообщитьПрогресс(Процент, ТекстПачек);

КонецПроцедуры

