Процедура NDFL_RDU_СоздатьДокументы(ТабличныйДокумент) Экспорт

	// IMDEV-7330-3,4,5 Принудительный сброс кэша на старте: если объект обработки переиспользуется
	// между вызовами (типичная ситуация для управляемой формы), модульные переменные не должны
	// "переживать" предыдущий прогон.
	NDFL_RDU_СтруктураКэшОборотов = Неопределено;
	NDFL_RDU_СтруктураКэшНКД = Неопределено;

	Попытка
		МассивПарКлиентУК = NDFL_RDU_СобратьПарыКлиентУКСУчетомОтборовДокументов();
		NDFL_RDU_ИнициализироватьКэшОборотовПоМассивуПар(МассивПарКлиентУК);
		МассивПарКлиентДатаНКД = NDFL_RDU_СобратьПарыКлиентДатаДляПредрасчетаНКД();
		NDFL_RDU_ИнициализироватьКэшНКДПоМассивуПар(МассивПарКлиентДатаНКД);
		ПродолжитьВызов(ТабличныйДокумент);
	Исключение
		NDFL_RDU_СтруктураКэшОборотов = Неопределено;
		NDFL_RDU_СтруктураКэшНКД = Неопределено;
		ВызватьИсключение;
	КонецПопытки;

	NDFL_RDU_СтруктураКэшОборотов = Неопределено;
	NDFL_RDU_СтруктураКэшНКД = Неопределено;

КонецПроцедуры

items.cf_body:
Процедура СоздатьДокументы(ТабличныйДокумент) Экспорт   

	// IMDEV-7330-3,4,5 Принудительный сброс кэша на старте: если объект обработки переиспользуется
	// между вызовами (типичная ситуация для управляемой формы), модульные переменные не должны
	// "переживать" предыдущий прогон.
	СтруктураКэшОборотов = Неопределено;
	СтруктураКэшНКД = Неопределено;

	МассивПарКлиентУК = СобратьПарыКлиентУКСУчетомОтборовДокументов();
	ИнициализироватьКэшОборотовПоМассивуПар(МассивПарКлиентУК);
	МассивПарКлиентДатаНКД = СобратьПарыКлиентДатаДляПредрасчетаНКД();
	ИнициализироватьКэшНКДПоМассивуПар(МассивПарКлиентДатаНКД);

	ОтборПоНомеруСтроки = НомерСтрокиС <> 0 Или НомерСтрокиПо <> 0;
	НачальноеВремя = ТекущаяДатаСеанса();

	СписокСообщений = Новый ТаблицаЗначений;
	СписокСообщений.Колонки.Добавить("ТекстСообщения");
	СписокСообщений.Колонки.Добавить("Объект");
	СписокСообщений.Колонки.Добавить("ЭтоОшибка");
	СписокСообщений.Колонки.Добавить("ЭтоКонтрагентСНулевымУдержанием");

	СписокНачислений = Новый Массив;

	Если НеСоздаватьДокументыПоКлиентамБезЦБ Тогда
		КлиентыСЦБ = СписокКлиентовСЦБ();	
	КонецЕсли;

	Для каждого СтрокаДокументов Из ДатыДокументов Цикл

		Если ОтборПоНомеруСтроки Тогда
			Если НомерСтрокиС <> 0 И СтрокаДокументов.НомерСтроки < НомерСтрокиС Тогда
				Продолжить;
			ИначеЕсли НомерСтрокиПо <> 0 И СтрокаДокументов.НомерСтроки > НомерСтрокиПо Тогда
				Прервать;
			КонецЕсли;
		КонецЕсли;

		Если НеСоздаватьДокументыПоКлиентамБезЦБ И КлиентыСЦБ.Найти(СтрокаДокументов.Клиент) = Неопределено Тогда
	   		ТекстСообщения = "Клиент выведен. " + СтрокаДокументов.СхемаРеинвестирования ;
			ДобавитьСообщение(СписокСообщений, ТекстСообщения, СтрокаДокументов.Клиент, Ложь, Истина);	
			Продолжить;
		КонецЕсли;

		СоздатьНачислениеНДФЛПоПортфелю(СтрокаДокументов, СписокСообщений);
		СоздатьНачислениеНДФЛПоУК(СтрокаДокументов, СписокСообщений, СписокНачислений)

	КонецЦикла;

	ОповеститьОРезидентахИностранныхГосударств(СписокСообщений);

	Если СоздаватьОплатуНДФЛ И ВариантЗаполнения = 2 Тогда

		Если Константы.ВестиПуловойУчет.Получить() = Истина Тогда

			Запрос = Новый Запрос;
			Запрос.Текст = 
			"ВЫБРАТЬ
			|	НачислениеНДФЛПоУправляющейКомпанииУдержания.ТипДохода КАК ТипДохода,
			|	НачислениеНДФЛПоУправляющейКомпанииУдержания.Ссылка КАК НачислениеНДФЛ,
			|	НачислениеНДФЛПоУправляющейКомпанииУдержания.Портфель КАК Портфель,
			|	СУММА(НачислениеНДФЛПоУправляющейКомпанииУдержания.СуммаКУдержанию) КАК Сумма
			|ИЗ
			|	Документ.НачислениеНДФЛПоУправляющейКомпании.Удержания КАК НачислениеНДФЛПоУправляющейКомпанииУдержания
			|ГДЕ
			|	НачислениеНДФЛПоУправляющейКомпанииУдержания.Ссылка В(&СписокНачислений)
			|
			|СГРУППИРОВАТЬ ПО
			|	НачислениеНДФЛПоУправляющейКомпанииУдержания.ТипДохода,
			|	НачислениеНДФЛПоУправляющейКомпанииУдержания.Портфель,
			|	НачислениеНДФЛПоУправляющейКомпанииУдержания.Ссылка
			|ИТОГИ
			|	СУММА(Сумма)
			|ПО
			|	ТипДохода";

			Запрос.УстановитьПараметр("СписокНачислений", СписокНачислений);

			РезультатЗапроса = Запрос.Выполнить();

			ВыборкаТипДохода = РезультатЗапроса.Выбрать(ОбходРезультатаЗапроса.ПоГруппировкам);

			Пока ВыборкаТипДохода.Следующий() Цикл

				ОплатаНалога = Документы.СписаниеСРасчетногоСчета.СоздатьДокумент();
				ОплатаНалога.Дата = НачалоДня(Период.ДатаОкончания) + 20*60*60 + 1;
				ОплатаНалога.ВидОперации = Перечисления.ВидыОперацийСписаниеДенежныхСредств.ПеречислениеНалога;
				ОплатаНалога.ВалютаДокумента = Справочники.Валюты.RUB;
				ОплатаНалога.Пуловая = Истина;
				ОплатаНалога.СубконтоДт1 = ВыборкаТипДохода.ТипДохода;
				ОплатаНалога.СубконтоДт2 = Справочники.Периоды.ПериодПоДатам(Перечисления.Периодичность.Год, Период.ДатаНачала, КонецДня(Период.ДатаОкончания));;
				ОплатаНалога.СчетПортфеля = СчетДляОплатыНалогов;
				ОплатаНалога.СуммаДокумента = ВыборкаТипДохода.Сумма;
				ОплатаНалога.НазначениеПлатежа = "Начисление НДФЛ";
				ЗаполнениеРеквизитовКлиентСервер.ДозаполнитьРеквизитыСписанияСРасчетногоСчета(ОплатаНалога, Ложь);
				ЗаполнениеРеквизитовКлиентСервер.ДозаполнитьРеквизитыСписанияСРасчетногоСчетаИзСтатьиДДС(ОплатаНалога);
				ОплатаНалога.СчетБанк = ПланыСчетов.Хозрасчетный.РасчетныеСчета;
				ОплатаНалога.БУ = Истина;
				ОплатаНалога.НУ = Истина;

				Выборка = ВыборкаТипДохода.Выбрать();

				ОплатаНалога.Портфели.Очистить();
				Пока Выборка.Следующий() Цикл
					Стр = ОплатаНалога.Портфели.Добавить();
					ЗаполнитьЗначенияСвойств(Стр, Выборка);
					Стр.НазначениеПлатежа = "Начисление НДФЛ";
					Стр.ДокументОснование = Выборка.НачислениеНДФЛ;
				КонецЦикла;

				Попытка
					ОплатаНалога.Записать(РежимЗаписиДокумента.Запись);
					ТекстСообщения = СтрШаблон("Записан документ %1 на сумму %2 по ставке %3", ОплатаНалога.Ссылка, Формат(ВыборкаТипДохода.Сумма, "ЧДЦ=2"), ВыборкаТипДохода.ТипДохода);
					ДобавитьСообщение(СписокСообщений, ТекстСообщения, ОплатаНалога.Ссылка);	
				Исключение
					ЗаписьЖурналаРегистрации(ЖурналРегистрацииСобытияКлиентСерверПовтИсп.ОбновлениеИнформационнойБазы().ЗаписьДокумента, УровеньЖурналаРегистрации.Ошибка, ОплатаНалога.Метаданные(), ОплатаНалога.Ссылка, ОписаниеОшибки());
					ДобавитьСообщение(СписокСообщений, ОписаниеОшибки(), ОплатаНалога.Ссылка, Истина);	
				КонецПопытки;

			КонецЦикла;

		Иначе

			ТекстСообщения = "В системе не ведется пуловый учет. Оплата не будет создана.";
			ДобавитьСообщение(СписокСообщений, ТекстСообщения);	

		КонецЕсли;

	КонецЕсли;	

	ВывестиЛог(СписокСообщений, ТабличныйДокумент, НачальноеВремя);

	СтруктураКэшОборотов = Неопределено;
	СтруктураКэшНКД = Неопределено;

КонецПроцедуры

