Процедура РассчитатьНДФЛ(ПараметрыРасчетаВнешн = Неопределено) Экспорт     

	ВнешнийКэшОборотов = ПараметрыРасчетаВнешн;   

	РаспределениеОбщихКомиссий = Новый ТаблицаЗначений;
	РаспределениеВознагражденияУК = Новый ТаблицаЗначений;

	ИнвестиционныйВычет = 0;
	Начисления.Очистить();
	ОбщиеРасходы.Очистить();

	ПараметрыРасчета = ПараметрыРасчета();   

	ТаблицаРасчета = Документы.НачислениеНДФЛПоПортфелю.ПустаяТаблицаРасчета();

	Расчет1530 = Расчет1530(ПараметрыРасчета);
	Расчет1530МНО = Рассчитать1530МНО(ПараметрыРасчета);
	Расчет1531 = Расчет1531(ПараметрыРасчета); 
	Расчет1532 = Расчет1532(ПараметрыРасчета);
	Расчет1536 = Расчет1536(ПараметрыРасчета);
	Расчет1537 = Расчет1537(ПараметрыРасчета);    
	Расчет2640 = Расчет2640(ПараметрыРасчета);   
	Расчет2792_1530 = Расчет2792(ПараметрыРасчета, "ПятилетняяЛьгота_1530");
	Расчет2792_1531 = Расчет2792(ПараметрыРасчета, "ПятилетняяЛьгота_1531");
	Расчет2792_1536 = Расчет2792(ПараметрыРасчета, "ПятилетняяЛьгота_1536");
	Расчет2793 = Расчет2793(ПараметрыРасчета);
	Если Не ПараметрыРасчета.НалоговыйПериодБольше2020 Тогда
		Расчет3023 = Расчет3023(ПараметрыРасчета);
	КонецЕсли;
	Расчет4800 = Расчет4800(ПараметрыРасчета);   
	Расчет4800Иное = Расчет4800Иное(ПараметрыРасчета);   

	ДобавитьРасчетПоЦБВТаблицу(ПараметрыРасчета, ТаблицаРасчета, Расчет1530, "НастройкиРасчетаПоВидамОбращаемости");	
	ДобавитьВСтруктуруКакСтроку(ТаблицаРасчета, Расчет2792_1530);  
	ДобавитьВСтруктуруКакСтроку(ТаблицаРасчета, Расчет2793);   
	Если Не ОбщегоНазначенияДУ.ЗначениеКонстанты("ИсключитьИзРасчетаНДФЛПроцентыПоМНО") Тогда
		ДобавитьВСтруктуруКакСтроку(ТаблицаРасчета, Расчет1530МНО);
	КонецЕсли;
	ДобавитьРасчетПоЦБВТаблицу(ПараметрыРасчета, ТаблицаРасчета, Расчет1531, "НастройкиРасчетаПоВидамОбращаемости"); 
	ДобавитьВСтруктуруКакСтроку(ТаблицаРасчета, Расчет2792_1531);   
	ДобавитьРасчетПоЦБВТаблицу(ПараметрыРасчета, ТаблицаРасчета, Расчет1536, "НастройкиРасчетаПоВидамОбращаемости"); 
	ДобавитьВСтруктуруКакСтроку(ТаблицаРасчета, Расчет2792_1536);   
	ДобавитьРасчетПоЦБВТаблицу(ПараметрыРасчета, ТаблицаРасчета, Расчет1537, "НастройкиРасчетаПоРЕПО"); 
	ДобавитьРасчетПоЦБВТаблицу(ПараметрыРасчета, ТаблицаРасчета, Расчет1532, "НастройкиРасчетаПо1532");

	Если Не ПараметрыРасчета.НалоговыйПериодБольше2020 Тогда
		ДобавитьРасчетПоЦБВТаблицу(ПараметрыРасчета, ТаблицаРасчета, Расчет3023, "НастройкиРасчетаПо3023");
	КонецЕсли;
	ДобавитьРасчетПоЦБВТаблицу(ПараметрыРасчета, ТаблицаРасчета, Расчет2640, "НастройкиРасчетаПо2640");
	ДобавитьРасчетПоЦБВТаблицу(ПараметрыРасчета, ТаблицаРасчета, Расчет4800, "НастройкиРасчетаПо4800");                          
	ДобавитьРасчетПоЦБВТаблицу(ПараметрыРасчета, ТаблицаРасчета, Расчет4800Иное, "НастройкиРасчетаПо4800Иное");                          

	ТаблицаРасчетаДоОбщихОперацийПоКлиенту = ТаблицаРасчета.Скопировать();	   
	ЗначенияРеквизитовПортфеля	= ОбщегоНазначения.ЗначенияРеквизитовОбъекта(Портфель, "УправляющаяКомпания, Клиент");
	НачисленияИзСтороннихСистем = Документы.НачислениеНДФЛПоУправляющейКомпании.НачисленияИзСтороннихСистем(ЗначенияРеквизитовПортфеля.УправляющаяКомпания, ЗначенияРеквизитовПортфеля.Клиент, Дата);
	СуммаЛьготИзСтороннихСистем = Документы.НачислениеНДФЛПоПортфелю.СуммаЛьготИзСтороннихСистем(НачисленияИзСтороннихСистем);

	Если Не ПараметрыРасчета.ЭтоВыдержанныйИИС  Тогда
		Документы.НачислениеНДФЛПоПортфелю.УчестьЛьготыПоКодам_2792_2793(ТаблицаРасчета, Дата, СуммаЛьготИзСтороннихСистем);
	КонецЕсли;

	Если Не ПараметрыРасчета.ОсуществленПереходНаПрогрессивнуюШкалу Тогда

		РаспределениеОбщихКомиссий = Документы.НачислениеНДФЛПоПортфелю.РасчетОбщихРасходов(ТаблицаРасчета, ПараметрыРасчета.ОбщиеКомиссии);
		РаспределениеВознагражденияУК = Документы.НачислениеНДФЛПоПортфелю.РасчетОбщихРасходов(ТаблицаРасчета, ПараметрыРасчета.ВознагражденияУК);

		Документы.НачислениеНДФЛПоПортфелю.ОтразитьОбщиеРасходыВНачислениях(ТаблицаРасчета, РаспределениеОбщихКомиссий, "ОбщиеКомиссии");
		Документы.НачислениеНДФЛПоПортфелю.ОтразитьОбщиеРасходыВНачислениях(ТаблицаРасчета, РаспределениеВознагражденияУК, "ВознагражденияУК");	

		Документы.НачислениеНДФЛПоПортфелю.ВыполнитьСальдирование(ТаблицаРасчета);

	Иначе

		Если ЗначениеЗаполнено(ПараметрыРасчета.ВознагражденияУК) Тогда
			НоваяСтрока = ОбщиеРасходы.Добавить();
			НоваяСтрока.ВидРасхода = Перечисления.ВидыОбщихРасходов.ВознаграждениеУК;
			НоваяСтрока.Сумма = ПараметрыРасчета.ВознагражденияУК;
		КонецЕсли;

		Если ЗначениеЗаполнено(ПараметрыРасчета.ОбщиеКомиссии) Тогда
			НоваяСтрока = ОбщиеРасходы.Добавить();
			НоваяСтрока.ВидРасхода = Перечисления.ВидыОбщихРасходов.Комиссии;
			НоваяСтрока.Сумма = ПараметрыРасчета.ОбщиеКомиссии;
		КонецЕсли;

	КонецЕсли;  

	Если ПараметрыРасчета.ЭтоВыдержанныйИИС Тогда
		ПодменитьКодыДоходаВычетаНаИИС(ТаблицаРасчета);
	КонецЕсли;

	Для каждого Расчет Из ТаблицаРасчета Цикл
		ДобавитьВСтруктуруКакСтроку(ПараметрыРасчета.ДанныеРасчетаКодов, Расчет.Расшифровка);
	КонецЦикла;   

	Документы.НачислениеНДФЛПоПортфелю.РассчитатьПоказателиДанныхРасчета(ПараметрыРасчета.ДанныеРасчетаКодов);

	ДанныеСправкиРасчета = Новый Структура;
	ДанныеСправкиРасчета.Вставить("ТаблицаРасчетаДоОбщихОперацийПоКлиенту", ТаблицаРасчетаДоОбщихОперацийПоКлиенту); 
	ДанныеСправкиРасчета.Вставить("ДанныеРасчетаКодов", ПараметрыРасчета.ДанныеРасчетаКодов); 
	ДанныеСправкиРасчета.Вставить("РаспределениеОбщихКомиссий", РаспределениеОбщихКомиссий);
	ДанныеСправкиРасчета.Вставить("РаспределениеВознагражденияУК", РаспределениеВознагражденияУК);
	ДанныеСправкиРасчета.Вставить("ОбщиеКомиссии", ПараметрыРасчета.ОбщиеКомиссии);
	ДанныеСправкиРасчета.Вставить("ВознагражденияУК", ПараметрыРасчета.ВознагражденияУК);
	ДанныеСправкиРасчета.Вставить("ВыводыЗадень");
	ДанныеСправкиРасчета.Вставить("ТаблицаПродажДляРасчетаЛьготПоКлиентамПодСанкциями", ПараметрыРасчета.ТаблицаПродажДляРасчетаЛьготПоКлиентамПодСанкциями);  

	ДанныеСправкиРасчета.Вставить("ПятилетняяЛьгота_1530", ПараметрыРасчета.ПятилетняяЛьгота_1530);
	ДанныеСправкиРасчета.Вставить("ПятилетняяЛьгота_1531", ПараметрыРасчета.ПятилетняяЛьгота_1531);
	ДанныеСправкиРасчета.Вставить("ПятилетняяЛьгота_1536", ПараметрыРасчета.ПятилетняяЛьгота_1536);
	ДанныеСправкиРасчета.Вставить("ЦБВысокотехнологичногоСектораЭкономики", ПараметрыРасчета.ЦБВысокотехнологичногоСектораЭкономики);

	ДобавитьВНачисления(ТаблицаРасчета);

	СуммаВыводовЗаДень = Документы.НачислениеНДФЛПоПортфелю.СуммаВыводовЗаДень(ПараметрыРасчета, Дата, Портфель);
	ЗаполнитьУдержания(ПараметрыРасчета, СуммаВыводовЗаДень, ДанныеСправкиРасчета);

	СправкаРасчет = Новый ХранилищеЗначения(ДанныеСправкиРасчета, Новый СжатиеДанных(9));    

	СправкиРасчет.ПослеЗаполненияДокумента(ЭтотОбъект); 

	ВнешнийКэшОборотов = Неопределено;      

КонецПроцедуры

