		СтруктураПакета = РасходыПоНКДПоКлиентамИДате(ВидыДляМассовогоКэшаНКД, Клиенты, ТекДата);

		Для Каждого Клиент Из Клиенты Цикл

			КлючКД = КлючКэшаНКД(Клиент, ТекДата);
			ПоКлиенту = Новый Структура;
			ПоКлиенту.Вставить("ПоПартиям", СтрокиПоКлиенту(СтруктураПакета.ПоПартиям, Клиент));
			ПоКлиенту.Вставить("ПоРегистраторам", СтрокиПоКлиенту(СтруктураПакета.ПоРегистраторам, Клиент));
			Результат.Вставить(КлючКД, ПоКлиенту);

